def normalize_operation_nature(value):
    return re.sub(r'[^0-9]', '', str(value) if value is not None else '')[:4]


def classify_operation_nature(value):
    return _OPERATIONS.get(normalize_operation_nature(value), 'NAO_CLASSIFICADA')


def is_purchase_operation(value):
    return classify_operation_nature(value) in ('COMPRAS', 'SERVICO_COMPRA')


def is_revenue_operation(value):
    return classify_operation_nature(value) in ('VENDA', 'SERVICO_VENDA')
